CREATE TABLE github_installations (
    id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    team_id text NOT NULL,
    installation_id bigint NOT NULL,
    account_login text NOT NULL,
    account_type text NOT NULL,
    repository_selection text NOT NULL,
    installed_by text NOT NULL,
    suspended_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Hosbah: the GitHub App installed on a GitHub account (user or organisation) and bound to one team.
-- A row is written only after the setup callback's single-use state (bound to the team and the
-- installing user) checked out AND GitHub itself confirmed the installation through the App's JWT
-- (GET /app/installations/{id}): account_login/account_type/repository_selection are GitHub's answer,
-- never the query string. installation_id is unique: one installation serves one team. Webhooks
-- (installation deleted/suspend/unsuspend, installation_repositories) update or delete the row in
-- system scope. installed_by is the user who completed the setup. No token is ever stored: clones
-- mint a fresh 1-hour installation token each time.
ALTER TABLE github_installations ADD CONSTRAINT github_installations_account_type_check CHECK (account_type IN ('User', 'Organization', 'Enterprise'));
ALTER TABLE github_installations ADD CONSTRAINT github_installations_selection_check CHECK (repository_selection IN ('all', 'selected'));
ALTER TABLE github_installations ADD CONSTRAINT github_installations_installation_check CHECK (installation_id > 0);
CREATE UNIQUE INDEX github_installations_installation_key ON github_installations (installation_id);
CREATE INDEX github_installations_team_idx ON github_installations (team_id);

-- Hosbah: GitHub webhook deliveries already handled (X-GitHub-Delivery), so a redelivery of the same
-- push queues nothing twice. Written in the same transaction as the deploys it queued. Pruned after
-- 30 days (GitHub redelivers only for a few days). System scope only.
CREATE TABLE github_deliveries (
    delivery_id text PRIMARY KEY,
    event text NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX github_deliveries_received_idx ON github_deliveries (received_at);
